public StagedFileReceipt receipt(String batchId,String itemId,RequestOptions options){Objects.requireNonNull(options);return transport.json("GET",prefix+"/sources/batches/"+Transport.id(batchId)+"/items/"+Transport.id(itemId)+"/receipt",null,options,transport.type(StagedFileReceipt.class));}
public StagedFileReceipt receipt(String batchId,String itemId){return receipt(batchId,itemId,RequestOptions.defaults());}
public CompletableFuture<StagedFileReceipt> receiptAsync(String batchId,String itemId,RequestOptions options){Objects.requireNonNull(options);return transport.jsonAsync("GET",prefix+"/sources/batches/"+Transport.id(batchId)+"/items/"+Transport.id(itemId)+"/receipt",null,options,transport.type(StagedFileReceipt.class));}
public CompletableFuture<StagedFileReceipt> receiptAsync(String batchId,String itemId){return receiptAsync(batchId,itemId,RequestOptions.defaults());}
public FileBatchView submit(String batchId,BulkAction input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.json("POST",prefix+"/sources/batches/"+Transport.id(batchId)+"/submit",input,options,transport.type(FileBatchView.class));}
public FileBatchView submit(String batchId,BulkAction input,String idempotencyKey){return submit(batchId,input,idempotencyKey,RequestOptions.defaults());}
public CompletableFuture<FileBatchView> submitAsync(String batchId,BulkAction input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.jsonAsync("POST",prefix+"/sources/batches/"+Transport.id(batchId)+"/submit",input,options,transport.type(FileBatchView.class));}
public CompletableFuture<FileBatchView> submitAsync(String batchId,BulkAction input,String idempotencyKey){return submitAsync(batchId,input,idempotencyKey,RequestOptions.defaults());}
public FileBatchView cancel(String batchId,BulkAction input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.json("POST",prefix+"/sources/batches/"+Transport.id(batchId)+"/cancel",input,options,transport.type(FileBatchView.class));}
