public CompletableFuture<FileBatchView> cancelAsync(String batchId,BulkAction input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.jsonAsync("POST",prefix+"/sources/batches/"+Transport.id(batchId)+"/cancel",input,options,transport.type(FileBatchView.class));}
