public FileBatchView reconcile(String batchId,String itemId,BulkAction input,String idempotencyKey){return reconcile(batchId,itemId,input,idempotencyKey,RequestOptions.defaults());}
public CompletableFuture<FileBatchView> reconcileAsync(String batchId,String itemId,BulkAction input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.jsonAsync("POST",prefix+"/sources/batches/"+Transport.id(batchId)+"/items/"+Transport.id(itemId)+"/reconcile",input,options,transport.type(FileBatchView.class));}
